    /// <summary>
    /// A small event bus shared by every plugin. Handlers run synchronously on the publisher's thread, each in
    /// its own try/catch: one plugin's broken handler never reaches another plugin.
    /// </summary>
    internal static class CampgroundEvents
    {
        private const string SectionName = "events";

        /// <summary>Subscribes; dispose the result to unsubscribe.</summary>
        internal static IDisposable Subscribe(string eventName, Action<JsonElement> handler)
        {
            var subscribers = SubscribersOf(eventName);
            var id = Guid.NewGuid().ToString("N");
            subscribers[id] = handler;
            return new Subscription(subscribers, id);
        }

        /// <summary>Publishes to every subscriber in every plugin.</summary>
        internal static void Publish<T>(string eventName, T payload)
        {
            var json = CampgroundRegistry.ToJson(payload);
            foreach (var value in SubscribersOf(eventName).Values)
            {
                if (value is Action<JsonElement> handler)
                {
                    try
                    {
                        handler(json);
                    }
                    catch (Exception)
                    {
                        // Fail open: a subscriber's bug is its own.
                    }
                }
            }
        }

        private static ConcurrentDictionary<string, object> SubscribersOf(string eventName)
        {
            var section = CampgroundRegistry.Section(SectionName);
            return section.GetOrAdd(eventName, _ => new ConcurrentDictionary<string, object>(StringComparer.Ordinal))
                as ConcurrentDictionary<string, object> ?? new ConcurrentDictionary<string, object>();
        }

        private sealed class Subscription : IDisposable
        {
            private readonly ConcurrentDictionary<string, object> _owner;
            private readonly string _id;

            internal Subscription(ConcurrentDictionary<string, object> owner, string id)
            {
                _owner = owner;
                _id = id;
            }

            public void Dispose() => _owner.TryRemove(_id, out _);
        }
    }
